import "./App.css"
import React, { useState, useEffect } from "react"
import { HashRouter as Router, Redirect, useLocation } from "react-router-dom" // Keep useLocation
import { DRAWER_WIDTH } from "./shared/constants"

import Networking from "./networking"

import SideDrawer from "./components/SideDrawer"
import TopBar from "./components/TopBar"
import InitialSetup from "./pages/InitialSetup"
import ManualControl from "./pages/ManualControl"
import RobotStatus from "./pages/RobotStatus"
import Path from "./pages/Path"
import PathFollowing from "./pages/PathFollowing"
import AutoDownhill from "./components/AutoDownhill"
import TestDataReadyPopUp from "./components/TestDataReadyPopUp"
import ResetMicroControllerModal from "./components/ResetMicroControllerModal"

import CssBaseline from "@material-ui/core/CssBaseline"
import { makeStyles } from "@material-ui/core/styles"
import PathRecorder from "./path-recorder"

let networking = new Networking("", false)

const pathRecorder = new PathRecorder() // initialized in App.tsx because components like TopBar needs its data

const useStyles = makeStyles((theme) => ({
  toolbar: theme.mixins.toolbar, // necessary for content to be below app bar
  content: {
    [theme.breakpoints.up("md")]: {
      width: `calc(100% - ${DRAWER_WIDTH}px)`,
      marginLeft: DRAWER_WIDTH,
    },
    padding: theme.spacing(3),
  },
  hiddenPage: { // For hiding am4chart on page switch instead of unmounting (chart will not reset view/toggle when switching pages)
    display: 'none',
  },
}));

export default function App() {
  const classes = useStyles()

  const [, setForceRerender] = useState({})
  const [topBarTitle, setTopBarTitle] = useState("")
  const [mobileOpen, setMobileOpen] = useState(false) // open status of the side menu in mobile screen

  function handleRobotConnect(id: string) {
    if (id === "useRecentId") {
      networking.socket.close()
      networking = new Networking(networking.lastConnectedId, networking.isConnectedOnce)
    } else {
      networking.socket.close()
      networking = new Networking(id, false)
    }
  }
  function handleRobotDisconnect() {
    networking.socket.close()
  }

  useEffect(() => {
    const id1 = setInterval(() => {
      setForceRerender({})
      const latitude = networking.robotState.gps.latitude // robot latitude
      const longitude = networking.robotState.gps.longitude // robot longitude
      const vehicleLatitude = networking.robotState.targetVehicle.latitude // vehicle latitude
      const vehicleLongitude = networking.robotState.targetVehicle.longitude // vehicle longitude
      if (networking.robotState.pathFollower.recordMode === 0) { // record mode 0 = robot
        // record robot path when requested
        pathRecorder.recordWhenRequested(latitude, longitude)
      }
      else if (networking.robotState.pathFollower.recordMode === 1) { // record mode 1 = vehicle
        // record vehicle path when requested
        pathRecorder.recordWhenRequested(vehicleLatitude, vehicleLongitude)
      }
    }, 100)

    return () => {
      clearInterval(id1)
    }
  }, [])
  
  return (
    <Router>
      <CssBaseline />
      <ResetMicroControllerModal networking={networking} />
      <AutoDownhill networking={networking} />
      <TestDataReadyPopUp networking={networking} />
      <TopBar
        networking={networking}
        setMobileOpen={setMobileOpen}
        topBarTitle={topBarTitle}
        pathRecorder={pathRecorder}
        handleRobotConnect={handleRobotConnect}
      />
      <SideDrawer networking={networking} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} />

      <main className={classes.content}>
        <div className={classes.toolbar} />
        {/* Sub-component to manage the route rendering and hiding for am4chart.*/}
        <RoutedPageManager
          networking={networking}
          setTopBarTitle={setTopBarTitle}
          pathRecorder={pathRecorder}
          handleRobotConnect={handleRobotConnect}
          handleRobotDisconnect={handleRobotDisconnect}
          classes={classes}
        />
      </main>
    </Router>
  )
}

//Manage routing and page visibility
interface RoutedPageManagerProps {
  networking: Networking
  setTopBarTitle: React.Dispatch<React.SetStateAction<string>>
  pathRecorder: PathRecorder
  handleRobotConnect: (id: string) => void
  handleRobotDisconnect: () => void
  classes: ReturnType<typeof useStyles>
}

function RoutedPageManager({
  networking,
  setTopBarTitle,
  pathRecorder,
  handleRobotConnect,
  handleRobotDisconnect,
  classes,
}: RoutedPageManagerProps) {
  const location = useLocation() 

  return (
    <>
      {/* InitialSetup Page */}
      <div className={location.pathname === "/initialsetup" ? "" : classes.hiddenPage}>
        <InitialSetup
          networking={networking}
          handleRobotConnect={handleRobotConnect}
          handleRobotDisconnect={handleRobotDisconnect}
          setTopBarTitle={setTopBarTitle}
        />
      </div>

      {/* ManualControl Page */}
      <div className={location.pathname === "/manualcontrol" ? "" : classes.hiddenPage}>
        <ManualControl
          networking={networking}
          setTopBarTitle={setTopBarTitle}
          pathRecorder={pathRecorder}
        />
      </div>

      {/* RobotStatus Page */}
      <div className={location.pathname === "/robotstatus" ? "" : classes.hiddenPage}>
        <RobotStatus networking={networking} setTopBarTitle={setTopBarTitle} />
      </div>

      {/* Path Page */}
      <div className={location.pathname === "/path" ? "" : classes.hiddenPage}>
        <Path networking={networking} setTopBarTitle={setTopBarTitle} pathRecorder={pathRecorder} />
      </div>

      {/* PathFollowing Page (This is where your chart is) */}
      <div className={location.pathname === "/pathfollowing" ? "" : classes.hiddenPage}>
        <PathFollowing
          networking={networking}
          setTopBarTitle={setTopBarTitle}
          pathRecorder={pathRecorder}
        />
      </div>

      {/* Handle the redirect for the root path */}
      {location.pathname === "/" && <Redirect to="/initialsetup" />}
    </>
  )
}
