import React, { useEffect, useState, useRef } from "react"

import { makeStyles } from "@material-ui/core/styles"

import Card from "@material-ui/core/Card"
import CardContent from "@material-ui/core/CardContent"
import Snackbar from "@material-ui/core/Snackbar"
import MuiAlert from "@material-ui/lab/Alert"
import InfoIcon from "@material-ui/icons/Info"
import IconButton from "@material-ui/core/IconButton"
import Modal from "@material-ui/core/Modal"
import Typography from "@material-ui/core/Typography"

import Networking from "../networking"

const useStyles = makeStyles((theme) => ({
  TempInfoButton: {
    paddingBottom: 1,
    paddingTop: 0,
    marginLeft: theme.spacing(1),
    color: "white",
  },
  TempInfoCard: {
    width: 400,
  },
  snackbar: {
    opacity: 0.85,
  },
}))

interface Props {
  networking: Networking
}

// Temp/voltage thresholds
const motor_threshold_temp = 185
const robot_threshold_temp = 140
const battery_threshold_voltage = 25.0

export default function Component({ networking }: Props) {
  const classes = useStyles()

  const [maxMotorTemp, setMaxMotorTemp] = useState(0)
  const [snackbarOpen, setSnackbarOpen] = useState(false)
  const [modalOpen, setModalOpen] = useState(false)
  const [maxRobotTemp, setMaxRobotTemp] = useState(0)
  const [batteryVoltage, setBatteryVoltage] = useState(networking.getAverageVoltage ? networking.getAverageVoltage() : 0)
  const savedRobotState = useRef(networking.robotState)
  savedRobotState.current = networking.robotState //Update state every render

  useEffect(() => {
    if (!networking.guiState.isConnected) {
        return
    }

    const intervalId = setInterval(() => {
      const robot = savedRobotState.current 
      const mcs = robot.motorControllers
      
      const max_t = Math.max(
        mcs.leftBack.windingTemperature,
        mcs.leftFront.windingTemperature,
        mcs.rightBack.windingTemperature,
        mcs.rightFront.windingTemperature
      )
      const max_robot_t = Math.max(
        robot.batteryTemperature,
        robot.robotTemperature
      )
  
      if (max_t !== 0) {
          setMaxMotorTemp(max_t)
      }
      if (max_robot_t !== 0) {
          setMaxRobotTemp(max_robot_t)
      }

      // Get the average from the shared history
      const averageVoltage = networking.getAverageVoltage() || 0
      setBatteryVoltage(averageVoltage)
    
      const isTempHigh = max_t > motor_threshold_temp || max_robot_t > robot_threshold_temp
      const isVoltageLow = averageVoltage < battery_threshold_voltage && averageVoltage !== 0 

      setSnackbarOpen(isTempHigh || isVoltageLow)
    }, 10000)

    return () => {
      clearInterval(intervalId)
    }
  }, [networking, networking.guiState.isConnected])

  // Text for different popups/dialogue scenarios
  let modalText: React.ReactNode = null
  let snackbarText: React.ReactNode = null
  
  if (maxMotorTemp > motor_threshold_temp && maxRobotTemp > robot_threshold_temp) { //Both motor and robot/battery temps high
    modalText = (
      <>
        •Both the motor winding temperature and robot/battery temperature are approaching temperature thresholds. <br/>
        •Upon the robot/battery temperature reaching the temperature threshold, robot operation will be disabled. <br/>
        •Upon the motor winding temperature reaching its threshold, STRIDE will enter descender mode if it is on a hill, 
        unless E-stopped, where it will hold until some more critical temperature threshold is reached. <br/>
        •Avoid leaving the STRIDE E-stopped on a hill whenever possible. <br/>
      </>
    )
    snackbarText = (
      <>
        Motor Temp: {maxMotorTemp} / 185F <br/> 
        Robot Temp: {maxRobotTemp} / 160F
      </>
    )
  }
  else if (maxMotorTemp > motor_threshold_temp && maxRobotTemp <= robot_threshold_temp) { //Only motor temps high
    modalText = (
      <>
        •Upon the motor winding temperature reaching its threshold, STRIDE will enter descender mode if it is on a hill, 
        unless E-stopped, where it will hold until some more critical temperature threshold is reached. <br/>
        •Avoid leaving the STRIDE E-stopped on a hill whenever possible. <br/> 
      </>
    )
    snackbarText = <>Motor Temp: {maxMotorTemp} / 185F</>
  }
  else if (maxMotorTemp <= motor_threshold_temp && maxRobotTemp > robot_threshold_temp) { //Only robot/battery temps high
    modalText = (
      <>Upon the robot/battery temperature reaching the temperature threshold, robot operation will be disabled. <br/></>
    )
    snackbarText = <>Robot Temp: {maxRobotTemp} / 160F</>
  }

  // Ensure low voltage text only shows up if voltage is low AND NOT zero
  if (batteryVoltage < battery_threshold_voltage && batteryVoltage !== 0) {
    modalText = (
      <>
        {modalText}
        •Battery voltage is low ({batteryVoltage.toFixed(1)}V). Please hot swap the battery soon. <br/>
      </>
    )
    snackbarText = (
      <>
        {snackbarText && <>{snackbarText}<br/></>}
        Battery Voltage: {batteryVoltage.toFixed(1)}V
      </>
    )
  }
  
  return (
    <div>
      <Modal
        style={{ display: "flex", alignItems: "center", justifyContent: "center" }}
        open={modalOpen}
        onClose={() => setModalOpen(false)}
      >
        <Card className={classes.TempInfoCard} variant="outlined">
          <CardContent>
            <Typography variant="body1">{modalText}</Typography>
          </CardContent>
        </Card>
      </Modal>
  
      <Snackbar
        className={classes.snackbar}
        open={snackbarOpen}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <MuiAlert elevation={6} variant="filled" severity="warning">
          {snackbarText}
          <IconButton
            className={classes.TempInfoButton}
            size="small"
            onClick={() => setModalOpen(true)}
          >
            <InfoIcon />
          </IconButton>
        </MuiAlert>
      </Snackbar>
    </div>
  )
}
